export function sealStatusText(status,t){return ({
 checking:t('正在比对本地内容','Checking local content'),consistent:t('本地内容一致','Local content consistent'),
 'digest-mismatch':t('内容与原指纹不一致','Content differs from its recorded fingerprint'),
 'missing-digest':t('缺少有效的定稿指纹','Valid seal fingerprint missing'),
 'invalid-project':t('项目内容未通过当前检查','Project data failed current checks'),
 'unsupported-version':t('规则版本不适用于当前预览','Rule version unsupported by this preview'),
 'metadata-mismatch':t('NFT 元数据指纹不一致','NFT metadata fingerprint mismatch'),
 'unsupported-content':t('文件字段与当前模板不一致','File fields differ from the current template'),
 unavailable:t('本地校验暂不可用','Local verification unavailable'),
 changed:t('内容变化，需要重新校验','Content changed; recheck required')
 })[status]??t('尚未核对定稿内容','Local seal not checked');}
export function sealPanel(record,check,h){
 const {t,esc,note,btn}=h,status=check?.status??'checking',ok=status==='consistent';
 return `<section class="panel integrity-panel" aria-label="${t('本地定稿校验','Local seal check')}"><div class="section-heading"><h2>${t('本地定稿校验','Local seal check')}</h2><span class="tag">${ok?'SHA-256':t('需要复核','REVIEW REQUIRED')}</span></div><p role="status">${sealStatusText(status,t)}</p>${note(ok?t('仅说明当前内容与本地保存的定稿指纹一致。没有验证作者签名、链上状态或合约安全性。','This only compares current content with a saved local fingerprint. It does not verify authorship, chain state or contract security.'):t('原方案与指纹保留。核对通过前，参与演示和以该定稿身份导出暂停；可以备份原数据，或复制成新草稿重新审核。','The original plan and fingerprint are preserved. Participation and sealed export are paused until consistent. Back up the original or copy it to a new review draft.'),ok?'':'warning')}${!ok?`<dl class="facts"><div><dt>${t('保存的指纹','Recorded fingerprint')}</dt><dd class="mono break">${esc(check?.recordedDigest??record.digest??'—')}</dd></div><div><dt>${t('当前内容计算结果','Current content digest')}</dt><dd class="mono break">${esc(check?.computedDigest??'—')}</dd></div></dl><div class="actions">${btn('seal-recheck',t('重新核对','Recheck'),'secondary',`data-id="${esc(record.id)}"`)}${btn('backup',t('备份原始本地数据','Back up original local data'),'secondary')}${btn('clone',t('复制为新草稿','Copy to new draft'),'text-link',`data-id="${esc(record.id)}"`)}</div>`:''}</section>`;
}
export function fileInspectionPage(inspection,h){
 const {t,esc,title,note,btn,link}=h,r=inspection?.result;
 const item=(label,value)=>`<div><dt>${label}</dt><dd class="mono break">${esc(value??'—')}</dd></div>`;
 return `${title('CHECK THE COMPLETE FILE',t('核对原文件，<br>再交给 Agent。','Check the complete file.<br>Then ask your Agent.'),t('只在浏览器读取导出的方案 JSON，重新计算指纹并比对当前模板。不会上传文件、连接钱包或改动原方案。','Read the exported JSON locally, recompute its fingerprint and compare it with the current template. No upload, wallet connection or original-plan changes.'))}<div class="agent-layout"><section class="panel"><h2>${t('选择完整方案 JSON','Choose the complete plan JSON')}</h2><label class="button secondary file-button">${t('打开方案文件','Open plan file')}<input id="verify-file" type="file" accept="application/json,.json"></label><p>${t('支持当前 v2 完整方案，最大 12 MiB。精简 Agent 摘要、草稿备份和运营测算不是完整发行方案。','Current v2 complete manifests up to 12 MiB. Compact Agent summaries, backups and operating plans are different formats.')}</p>${note(t('指纹不是作者签名。修改内容后同时重算指纹也可能通过本地一致性检查，因此还要独立核实项目来源；通过不等于审计或上线就绪。','A fingerprint is not an author signature. Someone who changes both data and fingerprint may pass a local consistency check. Verify the source independently. Passing is not an audit or launch readiness.'))}${link('#/agent',t('返回 Agent 指南 ↗','Back to Agent guide ↗'),'text-link')}</section><section class="panel" id="file-inspection" aria-live="polite"><h2>${t('核对结果','Check result')}</h2>${!inspection?`<p>${t('尚未选择文件。原有方案保持原样。','No file selected. Existing plans stay as they are.')}</p>`:inspection.error?note(esc(inspection.error),'warning'):`<p class="verification-label">${sealStatusText(r.status,t)}</p><dl class="facts">${item(t('文件名','File name'),inspection.name)}${item(t('项目','Project'),r.projectName)}${item(t('规则版本','Rule version'),r.rulesVersion)}${item(t('文件记录的指纹','Fingerprint in file'),r.recordedDigest)}${item(t('原文件重新计算','Recomputed source digest'),r.computedDigest)}${item(t('当前模板重新生成','Rebuilt current-template digest'),r.currentRulesDigest)}${item(t('NFT 元数据指纹','NFT metadata digest'),r.metadataHashMatches===null?t('不适用','Not applicable'):r.metadataHashMatches?t('一致','Consistent'):t('不一致','Mismatch'))}</dl>${r.status==='consistent'?note(t('文件内容和当前模板一致。仍仅供本地只读审核，未验证作者、合约、Gas 或资产。','File content matches the current template. Local read-only review only; authorship, contracts, Gas and assets are unverified.')):note(t('此文件未通过当前一致性检查，不能沿用其定稿身份或执行字段。原文件未改动。','This file did not pass current consistency checks. Its seal or execution fields cannot be adopted. The original file is unchanged.'),'warning')}${r.projectImportable?`<div class="actions">${btn('verify-to-draft',t('仅取项目数据，导入待审核草稿','Import project data as a review draft'),'secondary')}</div><p class="aside-help">${t('会分配新的本地 ID，清除原指纹、合约和执行标记，按当前规则重新审核。','A new local ID is assigned. Old fingerprints, contracts and execution flags are discarded; review under current rules.')}</p>`:''}`}</section></div>`;
}
